#define SLOTS 7
int table[SLOTS];
int occupied[SLOTS] = {0};

int hash(int key) { return key % SLOTS; }

void insert(int key) {
    int idx = hash(key);
    int probes = 0;
    while (occupied[idx] && probes < SLOTS) {
        idx = (idx + 1) % SLOTS; // linear probing
        probes++;
    }
    table[idx] = key;
    occupied[idx] = 1;
}

